function cfg = config()
%CONFIG  Shared settings for the Wi-Fi TDoA localization project.
%   cfg = config();
%
%   ONE source of truth for every block. Rules:
%     - Read from cfg, never hard-code numbers in your block.
%     - Do NOT edit this file yourself. Need a new field? Ask the integrator.
%     - SI units everywhere (m, s, Hz, W) unless the name says otherwise
%       (_dB, _dBm, _ppm).
%     - cfg.P0 (true TX position) is used ONLY by Block 1 and evaluation.
%
%   Sections:
%     0. General          4. Block 2 - RX
%     1. Physics          5. Block 3 - TDoA
%     2. Geometry         6. Block 4 - Localization
%     3. Block 1 - TX +   7. Block 5 - Tracking
%        Channel          8. Evaluation / sweeps
%     9. Derived values (computed, do not edit)

%% ===== 0. General ======================================================
cfg.seed        = 1;        % random seed -> rng(cfg.seed) in tests/main
cfg.Nmc         = 500;      % Monte Carlo trials for statistics
cfg.verbose     = true;     % print / plot extra info

%% ===== 1. Physics ======================================================
cfg.c           = 299792458;   % speed of light [m/s] (= physconst('LightSpeed'))
cfg.kB          = 1.380649e-23;% Boltzmann constant [J/K]
cfg.T0          = 290;         % noise temperature [K]

%% ===== Wi-Fi signal (shared by Blocks 1, 2, 3) =========================
cfg.fc          = 5.18e9;   % carrier frequency [Hz] (Wi-Fi channel 36)
cfg.B           = 20e6;     % channel bandwidth [Hz]: 20e6 / 40e6 / 80e6
cfg.fs          = cfg.B;    % sample rate [Hz] (Wi-Fi non-HT: fs = B)
cfg.psduLength  = 100;      % data payload length [bytes] (short packet)
cfg.mcs         = 0;        % modulation & coding scheme (0 = BPSK 1/2)

%% ===== 2. Geometry =====================================================
% Receivers: one row per RX, [x y] in metres. Row 1 = RX1 = reference.
cfg.Rx = [ 0   0 ;
          10   0 ;
          10  10 ;
           0  10 ];
cfg.nRx         = size(cfg.Rx, 1);
cfg.refIdx      = 1;        % reference receiver for TDoA

% TRUE transmitter position [x; y] in m.
% !! Block 1 and evaluation ONLY - Blocks 2-5 must never read this !!
cfg.P0          = [4; 3];

% Walls for reflections: one wall per row [x1 y1 x2 y2] in m.
% Empty matrix [] = no reflections (pure line of sight).
cfg.walls       = [ -2  -2  12  -2 ];   % one wall below the room

%% ===== 3. Block 1 - TX + Channel =======================================
cfg.Pt_dBm      = 0;        % TX power [dBm]
cfg.NF_dB       = 7;        % receiver noise figure [dB]
cfg.enableNoise = true;     % false = noise-free (debugging)
cfg.enableBounce= true;     % false = ignore cfg.walls
cfg.reflLoss_dB = 6;        % extra loss per wall bounce [dB]
cfg.maxT0       = 1e-6;     % unknown TX start time, uniform in [0, maxT0] [s]
cfg.guardSamples= 200;      % zero samples before and after the packet
cfg.cfo_ppm     = 10;       % carrier frequency offset, common to all RX [ppm]
cfg.randomPhase = true;     % random constant phase per RX (cables/hardware)

%% ===== 4. Block 2 - RX (sync + channel estimation) =====================
cfg.syncRx      = 1;        % RX used for packet detection + timing (= ref)
cfg.detThreshold= 0.5;      % wlanPacketDetect threshold (0..1)
cfg.useFineCFO  = true;     % fine CFO from L-LTF after coarse CFO
cfg.timingBackoff = 2;      % samples to back off from estimated L-LTF start
                            % (keep CP margin; same for ALL RX)

%% ===== 5. Block 3 - TDoA (delay, SNR, R) ===============================
cfg.zpFactor    = 16;       % zero-padding factor for CIR (IFFT size x16)
cfg.interp      = 'parabola';   % 'none' | 'parabola' | 'fft'
cfg.interpU     = 16;       % upsampling factor if interp = 'fft'
cfg.firstPath_dB= -10;      % first path = first peak within X dB of max
cfg.searchWin   = 32;       % search window around peak [samples]
cfg.Rmode       = 'theory'; % 'theory' (from SNR) | 'empirical' (Monte Carlo)

%% ===== 6. Block 4 - Localization + CRLB ================================
cfg.solver      = 'gradient';   % 'gradient' (ours) | 'lsqnonlin' (check)
cfg.maxIter     = 500;      % max solver iterations
cfg.tol         = 1e-6;     % stop when step < tol [m]
cfg.mu          = 1;        % normalized step size
cfg.Pinit       = mean(cfg.Rx, 1).';   % default initial guess = RX centre
cfg.ellipseConf = 0.95;     % confidence level for error ellipse

%% ===== 7. Block 5 - Tracking ===========================================
cfg.trackMethod = 'kalman'; % 'kalman' | 'particle'
cfg.dt          = 0.1;      % time between packets [s]
cfg.sigmaAcc    = 0.5;      % process noise: acceleration std [m/s^2]
cfg.nParticles  = 1000;     % if trackMethod = 'particle'
cfg.trajType    = 'line';   % test trajectory: 'static' | 'line' | 'circle'
cfg.trajSpeed   = 1.0;      % TX speed for test trajectory [m/s]
cfg.nSteps      = 100;      % number of packets in a tracking run

%% ===== 8. Evaluation / sweeps ==========================================
cfg.sweep.B      = [20e6 40e6 80e6];   % bandwidths to compare [Hz]
cfg.sweep.Pt_dBm = -40:5:10;           % TX powers (-> SNR sweep) [dBm]
cfg.sweep.interp = {'none', 'parabola', 'fft'};
cfg.saveResults  = true;               % save figures/data to results/

%% ===== 9. Derived values (computed - do not edit) ======================
cfg.cbw     = sprintf('CBW%d', round(cfg.B/1e6));  % 'CBW20' etc.
cfg.Ts      = 1 / cfg.fs;                  % sample period [s]
cfg.dRes    = cfg.c * cfg.Ts;              % range per sample [m] (~15 m @20 MHz)
cfg.lambda  = cfg.c / cfg.fc;              % wavelength [m]
cfg.N0      = cfg.kB * cfg.T0 * 10^(cfg.NF_dB/10);   % noise PSD [W/Hz]
cfg.noiseP  = cfg.N0 * cfg.B;              % in-band noise power [W]
cfg.nActive = 52 * round(cfg.B/20e6);       % active L-LTF subcarriers (52 @20 MHz)
cfg.nTDoA   = cfg.nRx - 1;                 % number of TDoAs
cfg.others  = setdiff(1:cfg.nRx, cfg.refIdx);  % non-reference RX indices
cfg.root    = fileparts(mfilename('fullpath'));  % project root folder

%% ===== Sanity checks ===================================================
assert(size(cfg.Rx, 2) == 2,               'cfg.Rx must be nRx x 2.');
assert(cfg.nRx >= 3,                       'Need at least 3 receivers.');
assert(any(cfg.refIdx == 1:cfg.nRx),       'cfg.refIdx out of range.');
assert(isequal(size(cfg.P0), [2 1]),       'cfg.P0 must be 2 x 1.');
assert(isempty(cfg.walls) || size(cfg.walls, 2) == 4, 'cfg.walls must be W x 4.');
assert(any(strcmp(cfg.interp, {'none','parabola','fft'})), 'Unknown cfg.interp.');
end
